-- AlterTable
ALTER TABLE "Activity" ADD COLUMN     "fromStatus" "ApplicationStatus",
ADD COLUMN     "toStatus" "ApplicationStatus";

-- Backfill: give every existing application a creation entry so its timeline
-- isn't empty. toStatus stays NULL — the status it was created with isn't
-- known. `id` uses a UUID because cuid() is generated by Prisma, not the DB.
INSERT INTO "Activity" ("id", "applicationId", "type", "description", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, a."id", 'APPLICATION_CREATED', 'Added', a."createdAt", NOW()
FROM "Application" a
WHERE NOT EXISTS (
  SELECT 1 FROM "Activity" act
  WHERE act."applicationId" = a."id" AND act."type" = 'APPLICATION_CREATED'
);
